static void slob_free_pages(void *b, int order) /* <=== slob_free_pages */ 
{
	struct page *sp = virt_to_page(b);

	if (current->reclaim_state)
		current->reclaim_state->reclaimed_slab += 1 << order;

	mod_node_page_state(page_pgdat(sp), NR_SLAB_UNRECLAIMABLE,
			    -(1 << order));
	__free_pages(sp, order);
}

static void kfree(void *p) /* <=== kfree */ 
{
	if (p)
		free(p);
}

static void slob_free(void *block, int size) /* <=== slob_free */ 
{
	struct page *sp;
	slob_t *prev, *next, *b = (slob_t *)block;
	slobidx_t units;
	unsigned long flags;
	struct list_head *slob_list;

	if (unlikely(ZERO_OR_NULL_PTR(block)))
		return;
	BUG_ON(!size);

	sp = virt_to_page(block);
	units = SLOB_UNITS(size);

	spin_lock_irqsave(&slob_lock, flags);

	if (sp->units + units == SLOB_UNITS(PAGE_SIZE)) {
		/* Go directly to page allocator. Do not pass slob allocator */
		if (slob_page_free(sp))
			clear_slob_page_free(sp);
		spin_unlock_irqrestore(&slob_lock, flags);
		__ClearPageSlab(sp);
		page_mapcount_reset(sp);
		slob_free_pages(b, 0);
		return;
	}

	if (!slob_page_free(sp)) {
		/* This slob page is about to become partially free. Easy! */
		sp->units = units;
		sp->freelist = b;
		set_slob(b, units,
			(void *)((unsigned long)(b +
					SLOB_UNITS(PAGE_SIZE)) & PAGE_MASK));
		if (size < SLOB_BREAK1)
			slob_list = &free_slob_small;
		else if (size < SLOB_BREAK2)
			slob_list = &free_slob_medium;
		else
			slob_list = &free_slob_large;
		set_slob_page_free(sp, slob_list);
		goto out;
	}

	/*
	 * Otherwise the page is already partially free, so find reinsertion
	 * point.
	 */
	sp->units += units;

	if (b < (slob_t *)sp->freelist) {
		if (b + units == sp->freelist) {
			units += slob_units(sp->freelist);
			sp->freelist = slob_next(sp->freelist);
		}
		set_slob(b, units, sp->freelist);
		sp->freelist = b;
	} else {
		prev = sp->freelist;
		next = slob_next(prev);
		while (b > next) {
			prev = next;
			next = slob_next(prev);
		}

		if (!slob_last(prev) && b + units == next) {
			units += slob_units(next);
			set_slob(b, units, slob_next(next));
		} else
			set_slob(b, units, next);

		if (prev + slob_units(prev) == b) {
			units = slob_units(b) + slob_units(prev);
			set_slob(prev, units, slob_next(b));
		} else
			set_slob(prev, slob_units(prev), b);
	}
out:
	spin_unlock_irqrestore(&slob_lock, flags);
}

static inline void kfree(void *p) /* <=== kfree */ 
{
	if (p >= __kfree_ignore_start && p < __kfree_ignore_end)
		return;
	free(p);
}

int security_locked_down(enum lockdown_reason what) /* <=== security_locked_down */ 
{
	return call_int_hook(locked_down, 0, what);
}

void *kmemdup(const void *src, size_t len, gfp_t gfp) /* <=== kmemdup */ 
{
	void *p;

	p = kmalloc_track_caller(len, gfp);
	if (p)
		memcpy(p, src, len);
	return p;
}

static void set_slob_page_free(struct page *sp, struct list_head *list) /* <=== set_slob_page_free */ 
{
	list_add(&sp->slab_list, list);
	__SetPageSlobFree(sp);
}

void kfree(const void *x) /* <=== kfree */ 
{
	struct page *page;
	void *object = (void *)x;

	trace_kfree(_RET_IP_, x);

	if (unlikely(ZERO_OR_NULL_PTR(x)))
		return;

	page = virt_to_head_page(x);
	if (unlikely(!PageSlab(page))) {
		unsigned int order = compound_order(page);

		BUG_ON(!PageCompound(page));
		kfree_hook(object);
		mod_node_page_state(page_pgdat(page), NR_SLAB_UNRECLAIMABLE,
				    -(1 << order));
		__free_pages(page, order);
		return;
	}
	slab_free(page->slab_cache, page, object, NULL, 1, _RET_IP_);
}

static inline void clear_slob_page_free(struct page *sp) /* <=== clear_slob_page_free */ 
{
	list_del(&sp->slab_list);
	__ClearPageSlobFree(sp);
}

static void spin_lock_irqsave(spinlock_t *lock, unsigned long f) /* <=== spin_lock_irqsave */ 
{
	spin_lock(lock);
}

static slobidx_t slob_units(slob_t *s) /* <=== slob_units */ 
{
	if (s->units > 0)
		return s->units;
	return 1;
}

void kfree(const void *objp) /* <=== kfree */ 
{
	struct kmem_cache *c;
	unsigned long flags;

	trace_kfree(_RET_IP_, objp);

	if (unlikely(ZERO_OR_NULL_PTR(objp)))
		return;
	local_irq_save(flags);
	kfree_debugcheck(objp);
	c = virt_to_cache(objp);
	if (!c) {
		local_irq_restore(flags);
		return;
	}
	debug_check_no_locks_freed(objp, c->object_size);

	debug_check_no_obj_freed(objp, c->object_size);
	__cache_free(c, (void *)objp, _RET_IP_);
	local_irq_restore(flags);
}

static int slob_last(slob_t *s) /* <=== slob_last */ 
{
	return !((unsigned long)slob_next(s) & ~PAGE_MASK);
}

static void spin_unlock_irqrestore(spinlock_t *lock, unsigned long f) /* <=== spin_unlock_irqrestore */ 
{
	spin_unlock(lock);
}

static void set_slob(slob_t *s, slobidx_t size, slob_t *next) /* <=== set_slob */ 
{
	slob_t *base = (slob_t *)((unsigned long)s & PAGE_MASK);
	slobidx_t offset = next - base;

	if (size > 1) {
		s[0].units = size;
		s[1].units = offset;
	} else
		s[0].units = -offset;
}

static inline int security_locked_down(enum lockdown_reason what) /* <=== security_locked_down */ 
{
	return 0;
}

static inline int slob_page_free(struct page *sp) /* <=== slob_page_free */ 
{
	return PageSlobFree(sp);
}

static slob_t *slob_next(slob_t *s) /* <=== slob_next */ 
{
	slob_t *base = (slob_t *)((unsigned long)s & PAGE_MASK);
	slobidx_t next;

	if (s[0].units < 0)
		next = -s[0].units;
	else
		next = s[1].units;
	return base+next;
}

void kfree(const void *block) /* <=== kfree */ 
{
	struct page *sp;

	trace_kfree(_RET_IP_, block);

	if (unlikely(ZERO_OR_NULL_PTR(block)))
		return;
	kmemleak_free(block);

	sp = virt_to_page(block);
	if (PageSlab(sp)) {
		int align = max_t(size_t, ARCH_KMALLOC_MINALIGN, ARCH_SLAB_MINALIGN);
		unsigned int *m = (unsigned int *)(block - align);
		slob_free(m, *m + align);
	} else {
		unsigned int order = compound_order(sp);
		mod_node_page_state(page_pgdat(sp), NR_SLAB_UNRECLAIMABLE,
				    -(1 << order));
		__free_pages(sp, order);

	}
}

int memcmp(const void *s1, const void *s2, size_t len) /* <=== memcmp */ 
{
	bool diff;
	asm("repe; cmpsb" CC_SET(nz)
	    : CC_OUT(nz) (diff), "+D" (s1), "+S" (s2), "+c" (len));
	return diff;
}

void kfree(void *p) /* <=== kfree */ 
{
	if (!p)
		return;
	uatomic_dec(&nr_allocated);
	if (kmalloc_verbose)
		printf("Freeing %p to malloc\n", p);
	free(p);
}

